  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Trametinib, a kinase inhibitor with an aminopyrimidine core and substituted phenyl amide, has an absolute oral bioavailability of 72.3% in patients, supporting high F for the query's similar heteroaromatic amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Regorafenib, a multi-aryl kinase inhibitor with a fluorophenyl and amide/urea linkages, has an absolute oral bioavailability of 69-83%, supporting high F for the query's analogous kinase-inhibitor-like structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Rimegepant, a heteroaromatic oral drug, has an absolute oral bioavailability of 64%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Apalutamide, a heteroaromatic oral drug, has an absolute oral bioavailability of approximately 100%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Safinamide, an amide-containing oral drug, has an absolute oral bioavailability of 95%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Alfuzosin, a quinazoline amide, has an absolute oral bioavailability of 49% under fed conditions, still above the 20% threshold and supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All experimental analogues show absolute oral bioavailability above 20%, with the most similar kinase inhibitors (trametinib, regorafenib) at 72% and 69-83%, respectively. Therefore, the query is predicted to have high oral bioavailability (F >= 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Potential acrylamide reactivity not directly assessed for its effect on oral bioavailability.",
    "No human PK data for the exact scaffold."
  ],
